<div class="page-heading"><div><p class="eyebrow">VERWALTUNG</p><h1>Berechtigungen</h1><p class="lead">Gruppen erhalten Rechte global oder in einem ausgewählten Speicherbereich.</p></div></div>
<section class="panel auth-panel"><h2>Gruppe und Geltungsbereich</h2><form method="get" action="/permissions" class="settings-form">
<label for="permission-group">Gruppe</label><select id="permission-group" name="group" required><option value="">Gruppe auswählen</option><?php foreach($data['choices']['groups'] as$group): ?><option value="<?= $e($group['id']) ?>" <?= ($data['selected_group']['id']??'')===$group['id']?'selected':'' ?>><?= $e($group['name']) ?></option><?php endforeach ?></select>
<label for="permission-space">Geltungsbereich</label><select id="permission-space" name="space"><option value="">Global, Hintergrundaufgaben</option><?php foreach($data['choices']['spaces'] as$space): ?><option value="<?= $e($space['id']) ?>" <?= ($data['selected_space']['id']??'')===$space['id']?'selected':'' ?>><?= $e($space['name']) ?></option><?php endforeach ?></select>
<button class="button" type="submit">Zuweisungen anzeigen</button></form></section>
<?php if($data['selected_group']!==null): ?>
<section class="panel auth-panel"><h2><?= $e($data['selected_group']['name']) ?> · <?= $e($data['selected_space']['name']??'Globale Rechte') ?></h2>
<p class="subtle">Profile ergänzen sich. Ein Entzug dieses Profils entfernt weder andere Rollen noch Rechte aus weiteren Gruppen. Die Bereichsverwaltung gewährt keine automatischen Dateirechte.</p>
<form method="post" action="/permissions/change" class="settings-form">
<input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="group" value="<?= $e($data['selected_group']['id']) ?>"><input type="hidden" name="space" value="<?= $e($data['selected_space']['id']??'') ?>">
<label for="permission-level">Berechtigungsprofil</label><select id="permission-level" name="selection" required><?php foreach($data['profiles'] as$row): ?><option value="<?= $e(json_encode([$row['profile']->id,$row['fingerprint']],JSON_THROW_ON_ERROR)) ?>" <?= !$row['available']?'disabled':'' ?>><?= $e($row['profile']->label) ?><?= $row['assigned']?' (zugewiesen)':' (nicht zugewiesen)' ?><?= !$row['available']?' (nicht verfügbar)':'' ?></option><?php endforeach ?></select>
<label for="permission-operation">Änderung</label><select id="permission-operation" name="operation"><option value="grant">Profil zuweisen</option><option value="revoke">Profil entziehen</option></select>
<label class="checkbox-label"><input type="checkbox" name="confirm" value="1" required> Diese Berechtigungsänderung bestätigen</label><button class="button" type="submit">Änderung speichern</button></form></section>
<section class="panel"><div class="panel-heading"><h2>Profile und aktueller Stand</h2></div><?php foreach($data['profiles'] as$row): ?><article class="group-row"><h3><?= $e($row['profile']->label) ?> <span class="badge <?= $row['assigned']?'badge-active':'badge-neutral' ?>"><?= $row['assigned']?'Zugewiesen':'Nicht zugewiesen' ?></span></h3><p class="subtle"><?= $e($row['profile']->description) ?></p><?php if(!$row['available']): ?><p>Dieses Profil ist wegen einer abweichenden vorhandenen Rollendefinition oder fehlender Pluginrechte gesperrt. Es wird nicht automatisch umgeschrieben.</p><?php endif ?></article><?php endforeach ?></section>
<?php endif ?>
